\begin{ex}%[8H3V3]
\immini[thm]{
Cho tam giác ${GHF}$ cân tại ${G}$ lấy điểm ${E}$ bất kỳ trên ${GH}$, lấy điểm ${J}$ trên tia đối của tia ${FG}$ sao cho $FJ=HE$. Từ ${E}$ kẻ đường thẳng song song với ${GF}$ cắt ${HF}$ tại ${I}$. Chọn khẳng định sai trong các khẳng định sau?  

\choice
{ Tứ giác ${EFJI}$ là hình bình hành   }
   { Tam giác ${EHI}$ là tam giác cân  }
     { \True  ${ GEIF }$ là hình thang cân }
    { $EI=FJ$ }
}{
\begin{tikzpicture}
            \coordinate (O) at (0, 1);
            \coordinate (D) at (-1.2, 1.99);
            \coordinate (C) at (2, 0);
            \coordinate (B) at (-2, 0);
            \coordinate (A) at (0, 5);
            \coordinate (F) at (-0.41, 0);
            \coordinate (E) at (2.9, -1.99);
            % Vẽ tứ giác
            \draw[thick] (D) -- (C)--(E)--(F)--(D);
            \draw[thick] (A) -- (B) -- (C)-- (A);

            % Ghi nhãn các điểm
            \node[below right] at (E) {$J$};
            \node[below left] at (B) {$H$};
            \node[above right] at (C) {$F$};
            \node[above left] at (D) {$E$};
            \node[above] at (A){$G$};
            \node[below left] at (F) {$I$};
           \draw
        ($(B)!0.5!(D)$)node[rotate=-40]{$/$};\draw ($(C)!0.5!(E)$)node[rotate=-40]{$/$};
    \end{tikzpicture}
}
\loigiai{
$\Delta{GHF}$ cân tại ${G}$ suy ra $\widehat{H} =\widehat{GFH}$.\\
Vì $EI//GF$ suy ra $ EIH=GFH $ (đồng vị)\\
Nên $\widehat{H} = \widehat{EIF}$  vậy $\Delta{EHI}$ là tam giác cân\\
$\Delta{EHI}$ là tam giác cân suy ra $EI=FJ$ suy ra tứ giác ${EFJI}$ là hình bình hành.\\
Khẳng định sai là ${ GEIF }$ là hình thang cân vì chưa đủ cơ sở.
}\end{ex}

