            \coordinate (O) at (0, 1);
            \coordinate (D) at (-1.2, 1.99);
            \coordinate (C) at (2, 0);
            \coordinate (B) at (-2, 0);
            \coordinate (A) at (0, 5);
            \coordinate (F) at (-0.41, 0);
            \coordinate (E) at (2.9, -1.99);
            % Vẽ tứ giác
            \draw[thick] (D) -- (C)--(E)--(F)--(D);
            \draw[thick] (A) -- (B) -- (C)-- (A);

            % Ghi nhãn các điểm
            \node[below right] at (E) {$J$};
            \node[below left] at (B) {$F$};
